import { readFile, writeFile } from 'node:fs/promises';
import { format } from 'prettier';

export async function browserClient() {
  const source = await readFile(new URL('../packages/binance-chat/client.js', import.meta.url), 'utf8');
  const entry = await readFile(new URL('../packages/binance-chat/browser-entry.js', import.meta.url), 'utf8');
  return format(
    '// Generated by npm run build:binance-client. Edit packages/binance-chat instead.\n' +
      source.replace('export function createBinanceChatClient', 'function createBinanceChatClient') +
      '\n' +
      entry,
    { parser: 'babel', singleQuote: true, printWidth: 110 },
  );
}
if (process.argv[1] === new URL(import.meta.url).pathname)
  await writeFile(
    new URL('../extensions/binance-browser/content.js', import.meta.url),
    await browserClient(),
  );
